import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Select,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { IncomeStatementInterimRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './BaoCaoKetQuaSxkdGiuaNienDoPage.module.css';

const TEST_ID = 'erp-b02-dn-interim';
const PAGE_ID = 'baocao-bao-cao-ket-qua-sxkd-giua-nien-do';
const TITLE = 'Báo cáo kết quả SXKD (Giữa niên độ)';
const DEFAULT_TEMPLATE = 'GLTC206';
const SHORT_FORM_SUPPORTED = new Set(['GLTC206']);
const TEMPLATE_ALLOW = new Set(['GLTC201', 'GLTC202', 'GLTC206']);

const PERIOD_TYPE_OPTIONS = [
  ...Array.from({ length: 12 }, (_, i) => {
    const v = String(i + 1).padStart(2, '0');
    return { value: v, label: `Tháng ${v}` };
  }),
  { value: '13', label: 'Quý 1' },
  { value: '14', label: 'Quý 2' },
  { value: '15', label: 'Quý 3' },
  { value: '16', label: 'Quý 4' },
  { value: '17', label: 'Sáu tháng đầu năm' },
  { value: '18', label: 'Sáu tháng cuối năm' },
  { value: '19', label: 'Cả năm' },
];

const TEMPLATE_OPTIONS = [
  { value: 'GLTC206', label: 'TT 200/2014/TT-BTC' },
  { value: 'GLTC201', label: 'QĐ/15' },
  { value: 'GLTC202', label: 'QĐ/48' },
];

const PERIOD_ALLOW = new Set(PERIOD_TYPE_OPTIONS.map(o => o.value));

const PERIOD_LABEL: Record<string, string> = Object.fromEntries(
  PERIOD_TYPE_OPTIONS.map(o => [o.value, o.label]),
);

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function yearOptions(): { value: string; label: string }[] {
  const y = new Date().getFullYear();
  const out: { value: string; label: string }[] = [];
  for (let i = y + 1; i >= y - 10; i -= 1) {
    out.push({ value: String(i), label: String(i) });
  }
  return out;
}

function rowClassName(row: IncomeStatementInterimRow): string {
  const parts: string[] = [];
  if (row.rowTag === 'Formula' || row.isFormula) parts.push(styles.rowToneFormula);
  if (row.rowTag === 'Eps') parts.push(styles.rowToneEps);
  if (row.isBold) parts.push(styles.rowBold);
  return parts.join(' ');
}

const BaoCaoKetQuaSxkdGiuaNienDoPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const years = useMemo(() => yearOptions(), []);

  const [periodType, setPeriodType] = useState('17');
  const [year, setYear] = useState(String(new Date().getFullYear()));
  const [shortForm, setShortForm] = useState(false);
  const [templateCode, setTemplateCode] = useState(DEFAULT_TEMPLATE);

  const [items, setItems] = useState<IncomeStatementInterimRow[]>([]);
  const [appliedPeriodType, setAppliedPeriodType] = useState('');
  const [appliedYear, setAppliedYear] = useState('');
  const [appliedShortForm, setAppliedShortForm] = useState(false);
  const [appliedTemplateCode, setAppliedTemplateCode] = useState(DEFAULT_TEMPLATE);
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [formatLabel, setFormatLabel] = useState('');
  const [periodLabel, setPeriodLabel] = useState('');
  const [circularText, setCircularText] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const shortFormDisabled = !SHORT_FORM_SUPPORTED.has(templateCode.trim());

  const handleTemplateChange = useCallback((value: string) => {
    const next = (value || '').trim() || DEFAULT_TEMPLATE;
    setTemplateCode(next);
    if (!SHORT_FORM_SUPPORTED.has(next)) {
      setShortForm(false);
    }
  }, []);

  const handleView = useCallback(() => {
    setFilterError('');
    const companyCode = sessionCompany();
    if (!companyCode) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }

    const pt = periodType.trim();
    if (!pt || !PERIOD_ALLOW.has(pt)) {
      setFilterError('Chọn kỳ');
      dispatchAppToast(dispatch, { message: 'Chọn kỳ', type: 'error' });
      return;
    }

    const yearNum = Number(year.trim());
    if (!year.trim() || !Number.isFinite(yearNum) || yearNum < 1900 || yearNum > 2100) {
      setFilterError('Chọn năm');
      dispatchAppToast(dispatch, { message: 'Chọn năm', type: 'error' });
      return;
    }

    const template = templateCode.trim();
    if (!template || !TEMPLATE_ALLOW.has(template)) {
      setFilterError('Chọn mẫu báo cáo');
      dispatchAppToast(dispatch, { message: 'Chọn mẫu báo cáo', type: 'error' });
      return;
    }

    if (shortForm && !SHORT_FORM_SUPPORTED.has(template)) {
      setFilterError('Mẫu này không hỗ trợ dạng rút gọn');
      dispatchAppToast(dispatch, {
        message: 'Mẫu này không hỗ trợ dạng rút gọn',
        type: 'error',
      });
      return;
    }

    setLoading(true);
    analyticsService
      .getIncomeStatementInterim({
        periodType: pt,
        year: yearNum,
        shortForm,
        templateCode: template,
        pageSize: 0,
      })
      .then(report => {
        setItems(Array.isArray(report.items) ? report.items : []);
        setAppliedPeriodType(pt);
        setAppliedYear(String(yearNum));
        setAppliedShortForm(shortForm);
        setAppliedTemplateCode(template);
        setFromDate((report.meta?.fromDate || '').trim());
        setToDate((report.meta?.toDate || '').trim());
        setFormatLabel(
          (report.meta?.formatLabel || (shortForm ? 'Dạng rút gọn' : 'Dạng đầy đủ')).trim(),
        );
        setPeriodLabel(
          (report.meta?.periodLabel || PERIOD_LABEL[pt] || '').trim(),
        );
        setCircularText(
          (report.meta?.circularText || report.meta?.ttQd || '').trim(),
        );
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được báo cáo kết quả SXKD giữa niên độ'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dispatch, periodType, shortForm, templateCode, year]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    setPeriodType('17');
    setYear(String(new Date().getFullYear()));
    setShortForm(false);
    setTemplateCode(DEFAULT_TEMPLATE);
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading) return;
    const shortSuffix = appliedShortForm ? '_short' : '';
    void exportExcel(
      '/accounting/income-statement-interim/export-excel',
      {
        periodType: appliedPeriodType,
        year: Number(appliedYear),
        shortForm: appliedShortForm,
        templateCode: appliedTemplateCode,
        pageSize: 0,
      },
      `bao-cao-ket-qua-sxkd-giua-nien-do_${appliedPeriodType}_${appliedYear}_${appliedTemplateCode}${shortSuffix}.xlsx`,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [
    appliedPeriodType,
    appliedShortForm,
    appliedTemplateCode,
    appliedYear,
    hasViewed,
    loading,
  ]);

  const handlePrint = useCallback(() => {
    if (!hasViewed) return;
    window.print();
  }, [hasViewed]);

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: !hasViewed || loading,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle = hasViewed
    ? `${periodLabel || PERIOD_LABEL[appliedPeriodType] || appliedPeriodType} · ${fromDate ? formatDate(fromDate) : '—'} – ${toDate ? formatDate(toDate) : '—'}${circularText ? ` · ${circularText}` : ''}${formatLabel ? ` · ${formatLabel}` : ''}`
    : '';

  const grid = (
    <div>
      {subtitle ? (
        <div className={styles.subtitle} data-testid={`${TEST_ID}-subtitle`}>
          {subtitle}
        </div>
      ) : null}
      {!hasViewed && !loading ? (
        <div className={styles.hint} data-testid={`${TEST_ID}-hint`}>
          Chọn kỳ, năm, mẫu báo cáo và bấm Xem
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Chỉ tiêu</th>
            <th className={reportStyles.colStt}>Mã số</th>
            <th className={reportStyles.colStt}>Thuyết minh</th>
            <th className={reportStyles.colRight}>Kỳ này</th>
            <th className={reportStyles.colRight}>Lũy kế</th>
            <th>Tài khoản nợ</th>
            <th>Tài khoản có</th>
            <th>Công thức tính</th>
          </tr>
        </thead>
        <tbody>
          {items.map((row, index) => (
            <tr
              key={`${row.lineCode}|${row.sortStt ?? ''}|${index}`}
              className={rowClassName(row)}
              data-testid={`${TEST_ID}-row-${index}`}
              data-row-tag={row.rowTag ?? ''}
              data-is-formula={row.isFormula ? '1' : '0'}
              data-is-bold={row.isBold ? '1' : '0'}
              data-giam-tru={row.giamTru ? '1' : '0'}
              data-line-code={row.lineCode ?? ''}
              data-tom-luoc={row.tomLuoc ? '1' : '0'}
              data-drillable={row.detailOk ? '1' : '0'}
            >
              <td>{row.indicatorName}</td>
              <td className={reportStyles.colStt}>{row.lineCode}</td>
              <td className={reportStyles.colStt}>{row.noteRef ?? ''}</td>
              <td className={reportStyles.colRight}>{formatVnd(row.currentAmount)}</td>
              <td className={reportStyles.colRight}>{formatVnd(row.ytdAmount)}</td>
              <td>{row.debitAccountFormula ?? ''}</td>
              <td>{row.creditAccountFormula ?? ''}</td>
              <td>{row.calcFormula ?? ''}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {hasViewed && items.length === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-chart-line' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-periodType`} onKeyDown={onEnterView}>
              <Select
                label="Kỳ"
                value={periodType}
                options={PERIOD_TYPE_OPTIONS}
                onChange={e => setPeriodType(e.target.value)}
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-year`} onKeyDown={onEnterView}>
              <Select
                label="Năm"
                value={year}
                options={years}
                onChange={e => setYear(e.target.value)}
                size="small"
              />
            </div>
            <div
              className={styles.shortFormField}
              data-testid={`${TEST_ID}-field-shortForm`}
              title={shortFormDisabled ? 'Mẫu này không hỗ trợ dạng rút gọn' : undefined}
            >
              <label>
                <input
                  type="checkbox"
                  checked={shortForm}
                  disabled={shortFormDisabled || loading}
                  onChange={e => setShortForm(e.target.checked)}
                />
                <span>Dạng rút gọn</span>
              </label>
            </div>
            <div data-testid={`${TEST_ID}-field-templateCode`} onKeyDown={onEnterView}>
              <Select
                label="Mẫu báo cáo"
                value={templateCode}
                options={TEMPLATE_OPTIONS}
                onChange={e => handleTemplateChange(e.target.value)}
                size="small"
              />
            </div>
            <Button
              variant="primary"
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
              onClick={handleView}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {grid}
      </LinPageLayout>
    </div>
  );
};

export default BaoCaoKetQuaSxkdGiuaNienDoPage;
